import sys
import hashlib
import os

def generate_checksum(secret: str, passphrase: str) -> str:
    return hashlib.sha256((secret + passphrase).encode()).hexdigest()

def read_vault() -> list:
    if not os.path.exists("vault.txt"):
        return []
    with open("vault.txt", "r") as f:
        return [line.strip().split("|") for line in f.readlines()]

def write_vault(vault: list) -> None:
    with open("vault.txt", "w") as f:
        for record in vault:
            f.write(f"{record[0]}|{record[1]}|{record[2]}\n")

def add_secret(label: str, secret: str, passphrase: str) -> None:
    vault = read_vault()
    checksum = generate_checksum(secret, passphrase)
    vault.append([label, secret, checksum])
    write_vault(vault)

def get_secret(label: str, passphrase: str) -> str | None:
    vault = read_vault()
    for record in vault:
        if record[0] == label:
            if generate_checksum(record[1], passphrase) == record[2]:
                return record[1]
    return None

def main():
    if len(sys.argv) != 3 or sys.argv[1] not in ("add", "get"):
        sys.exit(1)

    if sys.argv[1] == "add":
        label = sys.stdin.readline().strip()
        secret = sys.stdin.readline().strip()
        passphrase = sys.stdin.readline().strip()
        add_secret(label, secret, passphrase)
    else:
        label = sys.argv[2]
        passphrase = sys.stdin.readline().strip()
        secret = get_secret(label, passphrase)
        if secret is not None:
            print(secret)
        sys.exit(0 if secret is not None else 1)

if __name__ == "__main__":
    main()
